import {
  Mesh,
  PlaneGeometry,
  Vector3,
  Euler,
  Color,
  Texture,
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {[number, number, number]} position
 * @property {[number, number, number]} rotation
 * @property {[number, number, number]} scale
 * @property {Array<{name:string, params:any}>} cinematicPrimitives
 * @property {Array<{event:string, effect:string}>} interactions
 * @property {string} imageUrl
 * @property {string} depthMapUrl
 * @property {any} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>Texture} textureLoader
 * @property {(url:string)=>any} glbLoader
 * @property {Object<string,Function>} primitives
 * @property {(event:string, payload?:any)=>void} emit
 */

export default function createNode(config, ctx) {
  // Geometry
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // Load textures synchronously via context loaders
  const colorMap = ctx.textureLoader(config.imageUrl);
  const depthMap = ctx.textureLoader(config.depthMapUrl);

  // Material – node based
  const material = new MeshStandardNodeMaterial({
    map: colorMap,
    displacementMap: depthMap,
    displacementScale: 0.15, // subtle depth
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    color: new Color('#e8ecf2'), // paper
    envMapIntensity: 1,
  });

  // Mesh
  const plane = new Mesh(geometry, material);
  plane.position.set(...config.position);
  plane.rotation.set(...config.rotation);
  plane.scale.set(...config.scale);
  plane.castShadow = true;
  plane.receiveShadow = true;

  // Store GSAP timelines for cleanup
  const timelines = new Set();

  // Interaction handlers
  const handlers = {};

  // Hover – rise-in (y +0.15 → 0)
  handlers.hover = (event) => {
    if (!event || !event.type) return;
    const isEnter = event.type === 'mouseenter' || event.type === 'hoverenter';
    const targetY = isEnter ? 0.15 : 0;
    const tl = gsap.to(plane.position, {
      y: targetY,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.add(tl);
    tl.eventCallback('onComplete', () => timelines.delete(tl));
  };

  // Click – emit hub-home.select
  handlers.click = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-home.select');
    }
  };

  // Attach handlers to userData
  plane.userData.handlers = handlers;

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(plane, primitive.params);
      }
    }
  }

  // Cleanup
  plane.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();
    if (colorMap && colorMap.dispose) colorMap.dispose();
    if (depthMap && depthMap.dispose) depthMap.dispose();

    // Kill timelines
    for (const tl of timelines) {
      tl.kill();
    }
    timelines.clear();

    // Remove handlers reference
    plane.userData.handlers = null;
  };

  return plane;
}
